test('vatSummary calculates vat correctly for single line', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const issued = issueInvoice(r.value, []);
  const lineBase = lineTotal(issued.value.lines[0]);
  const discountAmount = roundCents(lineBase * (issued.value.lines[0].discountPercent / 100));
  const baseAfterDiscount = lineBase - discountAmount;
  const expectedVat = roundCents(baseAfterDiscount * 0.21);

  const result = vatSummary([issued.value]);
  assert.equal(result[0].vat, expectedVat);
});

test('vatSummary applies discount to base calculation', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 10 }],
  });
  const issued = issueInvoice(r.value, []);
  const lineBase = lineTotal(issued.value.lines[0]);
  const discountAmount = roundCents(lineBase * 0.1);
  const expectedBase = lineBase - discountAmount;

  const result = vatSummary([issued.value]);
  assert.equal(result[0].base, expectedBase);
});

test('vatSummary combines multiple lines with same VAT rate', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 3 },
    ],
  });
  const issued = issueInvoice(r.value, []);
  const line1Total = lineTotal(issued.value.lines[0]);
  const line1Discount = roundCents(line1Total * (issued.value.lines[0].discountPercent / 100));
  const line1Base = line1Total - line1Discount;
  const line1Vat = roundCents(line1Base * 0.21);

  const line2Total = lineTotal(issued.value.lines[1]);
  const line2Discount = roundCents(line2Total * (issued.value.lines[1].discountPercent / 100));
  const line2Base = line2Total - line2Discount;
  const line2Vat = roundCents(line2Base * 0.21);

  const expectedBase = line1Base + line2Base;
  const expectedVat = line1Vat + line2Vat;

  const result = vatSummary([issued.value]);
  assert.equal(result.length, 1);
  assert.equal(result[0].base, expectedBase);
  assert.equal(result[0].vat, expectedVat);
});

